 Image LoadBrandImage(){using(var stream=typeof(MainForm).Assembly.GetManifestResourceStream("TrayTidy.png")){if(stream==null)return Icon.ToBitmap();using(var source=Image.FromStream(stream))return new Bitmap(source);}}
 void TogglePause(){try{if(settings.Paused){if(!Save())return;settings.Paused=false;Persist();}else{settings.Paused=true;if(File.Exists(store)){var saved=json.Deserialize<Settings>(File.ReadAllText(store));saved.Paused=true;PersistValue(saved);}}UpdatePause();}catch(Exception e){settings.Paused=true;UpdatePause();MessageBox.Show(e.Message,"Could not save monitoring state");}}
 void UpdateSelection(){var f=folders.SelectedItem as Folder;folderTitle.Text=f==null?"Start with a folder":new DirectoryInfo(f.Path).Name;folderPath.Text=f==null?"Add a folder to begin defining rules.":f.Path;enabled.Enabled=f!=null;empty.Visible=f==null||f.Rules.Count==0;folders.Invalidate();UpdateStatus();}
 void SetDirty(bool value){if(loading)return;dirty=value;changes.Text=dirty?"●  UNSAVED CHANGES":"ALL CHANGES SAVED";changes.ForeColor=dirty?Color.FromArgb(245,193,111):Muted;UpdateSelection();}
 void UpdateStatus(){if(status==null)return;status.ForeColor=settings.Paused?Color.FromArgb(245,193,111):Mint;status.Text=(settings.Paused?"● PAUSED":"● MONITORING")+"   /   "+settings.Folders.Count+" folders   /   "+movedCount+" moved   /   "+(lastScan==default(DateTime)?"scan every 5s":"last scan "+lastScan.ToString("HH:mm:ss"));}
 void DrawFolder(object sender,DrawItemEventArgs e){if(e.Index<0||e.Index>=settings.Folders.Count)return;var f=settings.Folders[e.Index];bool active=(e.State&DrawItemState.Selected)!=0;using(var brush=new SolidBrush(active?Color.FromArgb(29,49,49):Surface))e.Graphics.FillRectangle(brush,e.Bounds);var name=new DirectoryInfo(f.Path).Name;if(string.IsNullOrEmpty(name))name=f.Path;var box=new Rectangle(e.Bounds.X+10,e.Bounds.Y+10,e.Bounds.Width-20,22);using(var font=new Font("Segoe UI Semibold",10))TextRenderer.DrawText(e.Graphics,(f.Enabled?"● ":"○ ")+name,font,box,active?Mint:Ink,TextFormatFlags.EndEllipsis);box.Y+=24;TextRenderer.DrawText(e.Graphics,f.Rules.Count+" rules · "+(f.Enabled?"enabled":"disabled"),Font,box,Muted,TextFormatFlags.EndEllipsis);}
 void OpenSelected(){var f=folders.SelectedItem as Folder;if(f!=null&&Directory.Exists(f.Path))System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo(f.Path){UseShellExecute=true});}
 void ShowPresets(){if(folders.SelectedItem==null)return;var menu=new ContextMenuStrip{BackColor=Surface,ForeColor=Ink};foreach(string name in new[]{"Documents","Images","Media","Archives","All four"}){string chosen=name;menu.Items.Add(name,null,delegate{var f=(Folder)folders.SelectedItem;rules.EndEdit();foreach(var rule in PresetRules(chosen))f.Rules.Add(rule);SelectFolder();SetDirty(true);});}menu.Closed+=delegate{menu.Dispose();};menu.Show(Cursor.Position);}
 public static List<Rule> PresetRules(string name){var result=new List<Rule>();string[] names={"Documents","Images","Media","Archives"};string[] patterns={"*.pdf;*.doc;*.docx;*.xls;*.xlsx;*.ppt;*.pptx;*.txt;*.md","*.png;*.jpg;*.jpeg;*.gif;*.webp;*.svg;*.heic","*.mp4;*.mkv;*.mov;*.mp3;*.wav;*.flac","*.zip;*.7z;*.rar;*.tar;*.gz"};for(int i=0;i<names.Length;i++)if(name==names[i]||name=="All four")result.Add(new Rule{Patterns=patterns[i],Destination=names[i],MinimumAgeSeconds=30});return result;}
 void ExportRules(){var f=folders.SelectedItem as Folder;if(f==null||!rules.EndEdit())return;using(var d=new SaveFileDialog{Filter="TrayTidy rules (*.json)|*.json",FileName="TrayTidy-rules.json"})if(d.ShowDialog(this)==DialogResult.OK)File.WriteAllText(d.FileName,json.Serialize(f.Rules));}
 void ImportRules(){var f=folders.SelectedItem as Folder;if(f==null)return;using(var d=new OpenFileDialog{Filter="TrayTidy rules (*.json)|*.json"})if(d.ShowDialog(this)==DialogResult.OK){var imported=json.Deserialize<List<Rule>>(File.ReadAllText(d.FileName));if(imported==null)throw new Exception("No rules in this file.");var copy=Snapshot();copy.Folders[settings.Folders.IndexOf(f)].Rules=imported;Engine.Validate(copy);f.Rules=imported;SelectFolder();SetDirty(true);WriteLog("Imported rules. Preview and save before monitoring.");}}
 protected override void Dispose(bool disposing){if(disposing){stop.Cancel();timer.Dispose();if(tray!=null)tray.Dispose();}base.Dispose(disposing);}
